/**
 * The bundled content sets, one per language: the four categories with their
 * sections, the four stories, and the sound inventory.
 *
 * The structure is small and always needed, so it is imported eagerly. Stories
 * are large and only one is needed at a time, so each is a separate chunk
 * fetched when a level opens.
 *
 * Both languages have the same categories and sections, but each has its own
 * stories, words and sounds, so everything here takes the language first.
 *
 * The JSON is generated by `scripts/build-content.mjs`; the casts are the one
 * place where its shape is trusted to match `$lib/types`.
 */
import { languages } from '$lib/languages';
import type { Category, CategoryContent, Language, Level, Section, Sound, Story } from '$lib/types';
import achterhoeksCategories from './achterhoeks/categories.json';
import achterhoeksSounds from './achterhoeks/sounds.json';
import groningsCategories from './gronings/categories.json';
import groningsSounds from './gronings/sounds.json';

interface ContentSet {
	categories: CategoryContent[];
	sounds: Sound[];
}

const sets: Record<Language, ContentSet> = {
	gronings: {
		categories: groningsCategories as unknown as CategoryContent[],
		sounds: groningsSounds as unknown as Sound[]
	},
	achterhoeks: {
		categories: achterhoeksCategories as unknown as CategoryContent[],
		sounds: achterhoeksSounds as unknown as Sound[]
	}
};

/* -------------------------------------------------------------------------- */
/* Sounds                                                                     */
/* -------------------------------------------------------------------------- */

export const sounds = (language: Language): Sound[] => sets[language].sounds;

const distractors = Object.fromEntries(
	languages.map(({ id }) => [id, sets[id].sounds.filter((sound) => sound.distractor !== false)])
) as Record<Language, Sound[]>;

/** The sounds that may be offered as a distractor. */
export const distractorSounds = (language: Language): Sound[] => distractors[language];

const soundsBySpelling = Object.fromEntries(
	languages.map(({ id }) => [id, new Map(sets[id].sounds.map((sound) => [sound.sound, sound]))])
) as Record<Language, Map<string, Sound>>;

export const getSound = (language: Language, spelling: string): Sound | undefined =>
	soundsBySpelling[language].get(spelling);

/* -------------------------------------------------------------------------- */
/* Categories, sections and levels                                            */
/* -------------------------------------------------------------------------- */

export const categories = (language: Language): CategoryContent[] => sets[language].categories;

export const getCategory = (language: Language, id: Category): CategoryContent | undefined =>
	sets[language].categories.find((category) => category.id === id);

export function getSection(
	language: Language,
	category: Category,
	section: string
): Section | undefined {
	return getCategory(language, category)?.sections.find((candidate) => candidate.id === section);
}

/** The localStorage key of a level, for example "gronings.luisteren.woorden.bragel". */
export const levelId = (
	language: Language,
	category: Category,
	section: string,
	story: string
): string => `${language}.${category}.${section}.${story}`;

/** The levels of one section, in the order their cards are shown. */
export function sectionLevels(language: Language, category: Category, section: string): Level[] {
	const stories = getSection(language, category, section)?.stories ?? [];
	return stories.map((story, index) => ({
		id: levelId(language, category, section, story),
		language,
		category,
		section,
		story,
		number: index + 1
	}));
}

/** Every level of one category. */
export function categoryLevels(language: Language, category: Category): Level[] {
	return (getCategory(language, category)?.sections ?? []).flatMap((section) =>
		sectionLevels(language, category, section.id)
	);
}

/** All 44 levels of one language. */
export function languageLevels(language: Language): Level[] {
	return categories(language).flatMap((category) => categoryLevels(language, category.id));
}

/** The levels of every language. Also the set of level keys that may exist in localStorage. */
export const allLevels = (): Level[] => languages.flatMap(({ id }) => languageLevels(id));

/* -------------------------------------------------------------------------- */
/* Stories                                                                    */
/* -------------------------------------------------------------------------- */

const storyModules = import.meta.glob('./*/stories/*.json', { import: 'default' }) as Record<
	string,
	() => Promise<unknown>
>;

/**
 * The stories of a language, in level order. Every section is played on the
 * same four stories, so the first section that mentions one fixes its position.
 */
export function storyKeys(language: Language): string[] {
	return [
		...new Set(
			categories(language).flatMap((category) =>
				category.sections.flatMap((section) => section.stories)
			)
		)
	];
}

const loaded = new Map<string, Story>();

/** Fetches one story, or returns it straight away once it has been fetched. */
export async function loadStory(language: Language, key: string): Promise<Story> {
	const path = `./${language}/stories/${key}.json`;
	const cached = loaded.get(path);
	if (cached) return cached;

	const load = storyModules[path];
	if (!load) throw new Error(`No ${language} story named "${key}" in the content set.`);

	const story = (await load()) as Story;
	loaded.set(path, story);
	return story;
}

/**
 * Fetches every story of a language. The picture games draw their distractors
 * from the other stories, so generating their items needs the whole set;
 * nothing else does.
 */
export const loadStories = (language: Language): Promise<Story[]> =>
	Promise.all(storyKeys(language).map((key) => loadStory(language, key)));

/** A story that has already been fetched, for use where awaiting is not an option. */
export const getLoadedStory = (language: Language, key: string): Story | undefined =>
	loaded.get(`./${language}/stories/${key}.json`);
